# Execute the actual summary method using a small standard-library tensor shim.
# This checks indexing, masking and formulas, not torch/autograd/BF16 behavior.
import ast, contextlib, itertools, json, math, random, types
from pathlib import Path

def indices(shape):
    return itertools.product(*(range(n) for n in shape))
def prod(shape):
    return math.prod(shape)
class Array:
    device=types.SimpleNamespace(type='cpu')
    def __init__(self,data,shape):
        self.data=list(data); self.shape=tuple(shape)
        assert len(self.data)==prod(self.shape)
    def at(self,index):
        offset=0
        for i,n in zip(index,self.shape): offset=offset*n+i
        return self.data[offset]
    def __getitem__(self,key):
        if not isinstance(key,tuple): key=(key,)
        if Ellipsis in key:
            p=key.index(Ellipsis)
            used=sum(k is not None and k is not Ellipsis for k in key)
            key=key[:p]+(slice(None),)*(len(self.shape)-used)+key[p+1:]
        used=sum(k is not None for k in key)
        key=key+(slice(None),)*(len(self.shape)-used)
        selectors=[]; shape=[]; axis=0
        for k in key:
            if k is None: selectors.append(('new',None)); shape.append(1)
            elif isinstance(k,int): selectors.append(('int',k)); axis+=1
            else:
                selected=list(range(self.shape[axis]))[k]
                selectors.append(('slice',selected)); shape.append(len(selected)); axis+=1
        out=[]
        for dest in indices(shape):
            src=[]; p=0
            for kind,value in selectors:
                if kind=='new': p+=1
                elif kind=='int': src.append(value)
                else: src.append(value[dest[p]]); p+=1
            out.append(self.at(src))
        return Array(out,shape)
    def _op(self,other,op):
        if not isinstance(other,Array): other=Array([other],())
        size=max(len(self.shape),len(other.shape))
        a=(1,)*(size-len(self.shape))+self.shape
        b=(1,)*(size-len(other.shape))+other.shape
        shape=[]
        for x,y in zip(a,b):
            assert x==y or x==1 or y==1,(a,b)
            shape.append(y if x==1 else x)
        vals=[]
        for idx in indices(shape):
            ia=tuple(0 if n==1 else i for n,i in zip(a,idx))[-len(self.shape):] if self.shape else ()
            ib=tuple(0 if n==1 else i for n,i in zip(b,idx))[-len(other.shape):] if other.shape else ()
            vals.append(op(self.at(ia),other.at(ib)))
        return Array(vals,shape)
    def __mul__(self,b): return self._op(b,lambda x,y:x*y)
    def __truediv__(self,b): return self._op(b,lambda x,y:x/y)
    def __and__(self,b): return self._op(b,lambda x,y:bool(x) and bool(y))
    def float(self): return Array(map(float,self.data),self.shape)
    def bool(self): return Array(map(bool,self.data),self.shape)
    def sum(self,dim,keepdim=False):
        dim=dim%len(self.shape)
        shape=list(self.shape); n=shape.pop(dim)
        vals=[]
        for idx in indices(shape):
            vals.append(sum(self.at(idx[:dim]+(j,)+idx[dim:]) for j in range(n)))
        if keepdim: shape.insert(dim,1)
        return Array(vals,shape)
    def mean(self,dim,keepdim=False): return self.sum(dim,keepdim)/self.shape[dim]
    def clamp_min(self,x): return Array((max(v,x) for v in self.data),self.shape)
    def expand_as(self,other): return self*Array([1.0]*len(other.data),other.shape)
    def new_zeros(self,shape,dtype=None): return Array([0.0]*prod(shape),shape)
