   n=max(1,len(active)); mapping={i:min(3,4*r//n) for r,i in enumerate(active)}
   for t in range(5): temporal.extend(i in mapping and (t==0 or mapping[i]==t-1) for i in range(length))
  temporal=Array(temporal,(B,5,length))
  # Nonzero junk in invalid values checks strict valid intersection in method.
  values=Array([rng.uniform(-2,3) if valid.at((z,i)) else 12345.0 for z in range(B) for i in range(length) for k in range(K+2)],(B,length,K+2))
  weights=Array([rng.uniform(-1.5,1.5) for _ in range(B*length)],(B,length))
  tasks=[Array([((i+z+a)%3==0) or (a==0 and i%2==0) for z in range(B) for i in range(length)],(B,length)) for a in range(4)]
  expected={}
  for source in ['"'joint','factorized']:
   for layout in ['separate','collapsed']:
    self=types.SimpleNamespace(item_width=K,source=source,layout=layout)
    got,counts=fn(self,values,weights,temporal,valid,tasks)
    assert got.shape==(B,5,4,K) and counts.shape==(B,5,4,1)
    for z in range(B):
     for t in range(5):
      active=[i for i in range(length) if valid.at((z,i)) and temporal.at((z,t,i))]
      summaries=[]
      for a in range(4):
       selected=[i for i in active if tasks[a].at((z,i))]
       rate=len(selected)/max(1,len(active))
       row=[]
       for k in range(K):
        total=sum(weights.at((z,i))*values.at((z,i,k)) for i in active)/math.sqrt(7)
        joint=sum(weights.at((z,i))*values.at((z,i,k)) for i in selected)/math.sqrt(7)
        row.append(joint if source=='joint' else rate*total)
       summaries.append(row)
       assert abs(counts.at((z,t,a,0))-math.log1p(len(selected))/math.log(101))<1e-12
      for a in range(4):
       for k in range(K):
        want=summaries[a][k] if layout=='separate' else sum(row[k] for row in summaries)/4
        assert abs(got.at((z,t,a,k))-want)<1e-10,(length,pattern,source,layout)
    expected[source,layout]=(got,counts)
    checks+=1
  # Sum-preserving collapse with all individual counts unchanged.
  for source in ['joint','factorized']:
   sep,c1=expected[source,'separate']; col,c2=expected[source,'collapsed']
   assert c1.data==c2.data
   for z in range(B):
    for t in range(5):
     for k in range(K):
      assert abs(sum(sep.at((z,t,a,k)) for a in range(4))-sum(col.at((z,t,a,k)) for a in range(4)))<1e-10
  # Arbitrary padded data and task bits have no effect.
  altered=Array([v if valid.at((z,i)) else -98765 for (z,i,k),v in zip(indices(values.shape),values.data)],values.shape)
  altered_tasks=[Array([v if valid.at((z,i)) else not v for (z,i),v in zip(indices(m.shape),m.data)],m.shape) for m in tasks]
  for source in ['joint','factorized']:
   for layout in ['separate','collapsed']:
    got,c=fn(types.SimpleNamespace(item_width=K,source=source,layout=layout),altered,weights,temporal,valid,altered_tasks)
    old,oc=expected[source,layout]
    assert got.data==old.data and c.data==oc.data
    checks+=1
# A content reassignment keeps F and all counts fixed, changes H in global bin.
